// pages/Feed.jsx
import React, { useEffect, useState, useRef } from 'react';
import ReviewCard from '../components/ReviewCard';
import { fetchReviews, createReview } from '../api/reviewApi';

// SNS-style composer: text + image/video upload + preview

function Feed() {
  const [reviews, setReviews] = useState([]);
  const authorRef = useRef();
  const textRef = useRef();
  const fileRef = useRef();
  const [preview, setPreview] = useState(null);

  const saveAndPrepend = (item) => {
    setReviews(prev => [item, ...prev]);
  };

  const handleFileChange = (e) => {
    const f = e.target.files?.[0];
    if (!f) { setPreview(null); return; }
    const reader = new FileReader();
    reader.onload = () => setPreview(reader.result);
    reader.readAsDataURL(f);
  };

  const handlePost = async (e) => {
    e.preventDefault();
    const author = authorRef.current?.value || '익명';
    const text = textRef.current?.value || '';
    let images = [];
    const f = fileRef.current?.files?.[0];
    if (f) {
      images = [await new Promise(res => {
        const fr = new FileReader(); fr.onload = () => res(fr.result); fr.readAsDataURL(f);
      })];
    }
    const payload = { author: { username: author }, title: '', text, images, createdAt: new Date().toISOString(), likes: 0 };
    try {
      const res = await createReview(payload);
      saveAndPrepend(res.data);
      // reset
      if (authorRef.current) authorRef.current.value = '';
      if (textRef.current) textRef.current.value = '';
      if (fileRef.current) fileRef.current.value = '';
      setPreview(null);
    } catch (err) {
      console.error('create review failed', err);
    }
  };

  useEffect(() => {
    const load = async () => {
      try {
        const res = await fetchReviews({ page: 1, limit: 20 });
        setReviews(res.data);
      } catch (err) {
        console.error('fetch reviews', err);
      }
    };
    load();
  }, []);

  return (
    <div style={{ padding: 20 }}>
      <h1>📝 리뷰 피드</h1>
      <p style={{ color: '#666' }}>사용자들이 올린 최신 리뷰를 확인하세요.</p>

      {/* Composer */}
      <div style={{ marginTop: 16, marginBottom: 18 }}>
        <form onSubmit={handlePost} style={{ border: '1px solid #eee', padding: 12, borderRadius: 12, background: '#fff' }}>
          <div style={{ display: 'flex', gap: 12 }}>
            <input ref={authorRef} placeholder="작성자 이름" style={{ flex: '0 0 140px', padding: 8, borderRadius: 8, border: '1px solid #ddd' }} />
            <textarea ref={textRef} placeholder="리뷰를 작성해보세요... (사진/동영상 첨부 가능)" style={{ flex: 1, padding: 8, borderRadius: 8, border: '1px solid #ddd' }} />
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              <input ref={fileRef} type="file" accept="image/*,video/*" onChange={handleFileChange} />
              <button type="submit" style={{ background: '#0070f3', color: '#fff', border: 'none', padding: '8px 12px', borderRadius: 8 }}>게시</button>
            </div>
          </div>
          {preview && (
            <div style={{ marginTop: 12 }}>
              {/* simple preview box */}
              <div style={{ border: '1px solid #f0f0f0', padding: 8, borderRadius: 8 }}>
                {preview.startsWith('data:video') ? (
                  <video src={preview} controls style={{ maxWidth: '100%', borderRadius: 8 }} />
                ) : (
                  <img src={preview} alt="preview" style={{ maxWidth: '100%', borderRadius: 8 }} />
                )}
              </div>
            </div>
          )}
        </form>
      </div>

      <div style={{ marginTop: 16 }}>
        {reviews.length === 0 ? (
          <p style={{ color: '#999' }}>아직 리뷰가 없습니다.</p>
        ) : (
          reviews.map(r => (
            <ReviewCard key={r._id} id={r._id} username={r.author?.username || '익명'} title={r.title} text={r.text} images={r.images} createdAt={r.createdAt} likes={r.likes} />
          ))
        )}
      </div>
    </div>
  );
}

export default Feed;
